/**
 * M-F1 quick wins. SAMPLE is nondeterministic by definition, so its tests are semantic predicates (the sampled value
 * must be one of the group's eligible values; empty input leaves the binding absent), never value comparisons against
 * the generic arm. The memoReadMask Extension case is pinned structurally.
 */
public class LmdbNativeQuickWinsTest {

	private static final String EX = "http://example.com/";

	@TempDir
	File dataDir;

	private SailRepository repository;

	@BeforeEach
	public void setUp() {
		repository = new SailRepository(new LmdbStore(dataDir, new LmdbStoreConfig("spoc,posc,ospc")));
		repository.init();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			conn.begin();
			ValueFactory vf = conn.getValueFactory();
			IRI p = vf.createIRI(EX, "p");
			conn.add(vf.createIRI(EX, "s1"), p, vf.createLiteral("a"));
			conn.add(vf.createIRI(EX, "s1"), p, vf.createLiteral("b"));
			conn.add(vf.createIRI(EX, "s2"), p, vf.createLiteral("c"));
			conn.commit();
		}
	}

	@AfterEach
	public void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	@Test
	public void groupedSampleCompilesNativelyAndSatisfiesTheSemanticPredicate() {
		String query = "SELECT ?s (SAMPLE(?o) AS ?v) WHERE { ?s <" + EX + "p> ?o } GROUP BY ?s";
		long compiledBefore = LmdbNativeAggregateCompiler.COMPILED.get();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			List<BindingSet> rows = QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
			assertThat(rows).hasSize(2);
			for (BindingSet row : rows) {
				String subject = row.getValue("s").stringValue();
				String sampled = row.getValue("v").stringValue();
				Set<String> eligible = subject.endsWith("s1") ? Set.of("a", "b") : Set.of("c");
				assertThat(eligible).as("SAMPLE must return one of the group's values").contains(sampled);
			}
		}
		assertThat(LmdbNativeAggregateCompiler.COMPILED.get() - compiledBefore)
				.as("SAMPLE must compile natively (previously a root decline)")
				.isGreaterThanOrEqualTo(1);
	}

	@Test
	public void ungroupedSampleOverEmptyInputLeavesTheBindingAbsent() {
		String query = "SELECT (SAMPLE(?o) AS ?v) WHERE { ?s <" + EX + "absent> ?o }";
		try (SailRepositoryConnection conn = repository.getConnection()) {
			List<BindingSet> rows = QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
			assertThat(rows).hasSize(1);
			assertThat(rows.get(0).hasBinding("v")).isFalse();
		}
	}

	@Test
	public void distinctSampleIsValid() {
		String query = "SELECT (SAMPLE(DISTINCT ?o) AS ?v) WHERE { ?s <" + EX + "p> ?o }";
		try (SailRepositoryConnection conn = repository.getConnection()) {
			List<BindingSet> rows = QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
			assertThat(rows).hasSize(1);
			assertThat(Set.of("a", "b", "c")).contains(rows.get(0).getValue("v").stringValue());
		}
	}

	/** M-F3: grouped GROUP_CONCAT compiles natively; parts joined by the separator in some encounter order. */
	@Test
	public void groupConcatCompilesNativelyAndJoinsGroupValues() {
		String query = "SELECT ?s (GROUP_CONCAT(?o; SEPARATOR=\"|\") AS ?c) WHERE { ?s <" + EX + "p> ?o } GROUP BY ?s";
		long compiledBefore = LmdbNativeAggregateCompiler.COMPILED.get();
		try (SailRepositoryConnection conn = repository.getConnection()) {
			List<BindingSet> rows = QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
			assertThat(rows).hasSize(2);
			for (BindingSet row : rows) {
				String subject = row.getValue("s").stringValue();
				String concatenated = row.getValue("c").stringValue();
				if (subject.endsWith("s1")) {
					assertThat(concatenated).isIn("a|b", "b|a");
				} else {
					assertThat(concatenated).isEqualTo("c");
				}
			}
		}
		assertThat(LmdbNativeAggregateCompiler.COMPILED.get() - compiledBefore)
				.as("GROUP_CONCAT must compile natively (previously a root decline)")
				.isGreaterThanOrEqualTo(1);
	}

	/** M-F3: GROUP_CONCAT over empty input is the empty string literal, exactly like the generic collector. */
	@Test
	public void groupConcatOverEmptyInputIsEmptyString() {
		String query = "SELECT (GROUP_CONCAT(?o) AS ?c) WHERE { ?s <" + EX + "absent> ?o }";
		try (SailRepositoryConnection conn = repository.getConnection()) {
			List<BindingSet> rows = QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
			assertThat(rows).hasSize(1);
			assertThat(rows.get(0).getValue("c").stringValue()).isEmpty();
		}
	}

	/** M-F3: DISTINCT deduplicates before concatenation (multiplicity injected via a self-join). */
	@Test
	public void groupConcatDistinctDeduplicates() {
		String query = "SELECT (GROUP_CONCAT(DISTINCT ?o; SEPARATOR=\",\") AS ?c) "
				+ "WHERE { ?s <" + EX + "p> ?o . ?s <" + EX + "p> ?other }";
		try (SailRepositoryConnection conn = repository.getConnection()) {
			List<BindingSet> rows = QueryResults.asList(conn.prepareTupleQuery(query).evaluate());
			assertThat(rows).hasSize(1);
			List<String> parts = List.of(rows.get(0).getValue("c").stringValue().split(","));
			assertThat(parts).containsExactlyInAnyOrder("a", "b", "c");
		}
	}

	/** M-F1: an Extension of plain slot/constant copies no longer degrades memoReadMask to sticky -1. */
	@Test
	public void extensionOfPlainCopiesHasAnExactMemoReadMask() {
		SlotPlan values = SlotPlan.values(new ValuesRow[] { new ValuesRow(new int[] { 0 }, new long[] { 42L }) });
		SlotPlan extension = SlotPlan.extension(values, new CopyBinding[] { CopyBinding.slot(1, 0) });
		assertThat(LmdbNativeAggregateCompiler.memoReadMask(extension))
				.as("slot-copy extensions are pure functions of their argument's row stream")
				.isEqualTo(0b11L);
		SlotPlan computedLike = SlotPlan.extension(values, new CopyBinding[] {
				CopyBinding.computed(1, new LmdbNativeCompiledInlineId(0L, true, slots -> 0L)) });
		assertThat(LmdbNativeAggregateCompiler.memoReadMask(computedLike))
				.as("computed copies keep the conservative sticky mask")
				.isEqualTo(-1L);
	}

	private List<String> rows(String query) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			return QueryResults.asList(conn.prepareTupleQuery(query).evaluate())
					.stream()
					.map(BindingSet::toString)
					.collect(Collectors.toList());
		}
	}
}
